pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 value) public {
        // Restrict to avoid overflow in reference, but allow large values that break the buggy version
        vm.assume(value <= type(uint256).max / 2); // enough for add to not overflow in reference
        vm.deal(user, value);
        vm.prank(user);
        uint256 before = c.getBalance(user);
        // Ensure the addition does not overflow for the reference
        vm.assume(before + value >= before);
        c.addToBalance{value: value}();
        uint256 after = c.getBalance(user);
        // Reference C satisfies: after <= before + value
        assertTrue(after <= before + value);
    }
}

