// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 initialBalance, uint256 deposit) public {
        // Ensure the user has enough ETH to send
        vm.assume(deposit <= type(uint256).max - initialBalance);
        vm.deal(user, deposit);

        // Set up initial balance by calling addToBalance
        vm.prank(user);
        c.addToBalance{value: initialBalance}();
        uint256 prevBalance = c.getBalance(user);

        // Now call addToBalance with the deposit
        vm.prank(user);
        bool success = false;
        try c.addToBalance{value: deposit}() {
            success = true;
        } catch {
            success = false;
        }

        uint256 newBalance = c.getBalance(user);
        // The rule: If the call succeeded, the new balance must equal prevBalance + deposit
        // If it reverted (due to overflow in the reference), the balance must still be prevBalance
        if (success) {
            assertTrue(newBalance == prevBalance + deposit, "Balance should be sum");
        } else {
            // If it reverted, the balance must not have changed (cannot overflow state)
            assertTrue(newBalance == prevBalance, "Balance unchanged on revert");
        }
    }
}

